(()=>{
'use strict';
if(window.__gtavModsAdditionalV1)return;window.__gtavModsAdditionalV1=true;
const API='/api/additional-mods';
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="lib-icon" aria-hidden="true"><use href="assets/icons.svg#${name}"></use></svg>`;
async function getItems(){try{const r=await fetch(API,{cache:'no-store'});if(!r.ok)throw new Error();const d=await r.json();return Array.isArray(d.mods)?d.mods.filter(x=>x.published!==false):[]}catch{return[]}}
function waitForLibrary(){return new Promise(resolve=>{const ready=()=>document.querySelector('.library-feed')&&document.querySelector('.library-filters');if(ready()){resolve();return}const o=new MutationObserver(()=>{if(ready()){o.disconnect();resolve()}});o.observe(document.documentElement,{childList:true,subtree:true});setTimeout(()=>{o.disconnect();resolve()},7000)})}
function childRows(items){return items.map((x,i)=>`<a class="collection-row" data-mod-id="${safe(x.id)}" href="${safe(x.downloadUrl)}" target="_blank" rel="noopener noreferrer"><span class="collection-index">${String(i+1).padStart(2,'0')}</span><span class="collection-copy"><strong>${safe(x.title)}</strong><small>Additional Mod</small></span><span class="collection-action">${icon('download-modern')}</span></a>`).join('')}
function buildCard(items){const article=document.createElement('article');article.className='library-card has-children additional-collection';article.dataset.id='additional-mods';article.dataset.type='additional';article.dataset.count=String(items.length);article.dataset.search=['Additional Mods','Extra standalone mods',...items.map(x=>x.title)].join(' ').toLowerCase();article.innerHTML=`<div class="library-media abstract-media"><span class="media-icon">${icon('package')}</span><strong>${String(items.length).padStart(2,'0')}</strong><small>ADDITIONAL MODS</small></div><div class="library-card-body"><div class="library-card-meta"><span>${icon('package')}Additional</span><span>${items.length} download${items.length===1?'':'s'}</span></div><h3>Additional Mods</h3><p class="library-card-subtitle">${items.length} extra mod${items.length===1?'':'s'}</p><p class="library-card-description">Extra standalone downloads collected in one place.</p><div class="library-tags"><span>${items.length} mods</span><span>Extras</span></div><div class="library-actions"><button class="collection-toggle" type="button" aria-expanded="false"><span>View ${items.length} mods</span>${icon('chevron-down')}</button></div></div><div class="collection-panel" hidden>${childRows(items)}</div>`;const toggle=article.querySelector('.collection-toggle'),panel=article.querySelector('.collection-panel');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));panel.hidden=open;article.classList.toggle('is-open',!open)});return article}
function updateStats(items){const stats=document.querySelectorAll('.library-stats>span strong');if(stats[0]&&!stats[0].dataset.additionalCounted){stats[0].textContent=String((Number.parseInt(stats[0].textContent,10)||0)+items.length);stats[0].dataset.additionalCounted='1'}if(stats[1]&&!stats[1].dataset.additionalCounted){stats[1].textContent=String((Number.parseInt(stats[1].textContent,10)||0)+1);stats[1].dataset.additionalCounted='1'}const all=document.querySelector('.library-filters [data-filter="all"] span');if(all&&!all.dataset.additionalCounted){all.textContent=String((Number.parseInt(all.textContent,10)||0)+items.length);all.dataset.additionalCounted='1'}}
function syncAdditional(card,items){const search=document.querySelector('#library-search'),active=document.querySelector('.library-filters .is-active')?.dataset.filter||'all',q=(search?.value||'').trim().toLowerCase(),matches=!q||card.dataset.search.includes(q);card.hidden=!((active==='all'||active==='additional')&&matches);if(active==='additional'){document.querySelectorAll('.library-card:not(.additional-collection)').forEach(x=>x.hidden=true);const count=document.querySelector('.result-count');if(count)count.textContent=`${matches?items.length:0} download${(matches?items.length:0)===1?'':'s'}`;const heading=document.querySelector('#library-heading');if(heading)heading.textContent='Additional Mods'}}
async function init(){if(document.body?.dataset.page!=='downloads')return;await waitForLibrary();const feed=document.querySelector('.library-feed'),filters=document.querySelector('.library-filters');if(!feed||!filters||document.querySelector('.additional-collection'))return;const items=(await getItems()).sort((a,b)=>(a.sortOrder||100)-(b.sortOrder||100));if(!items.length)return;const card=buildCard(items);feed.append(card);const filter=document.createElement('button');filter.type='button';filter.dataset.filter='additional';filter.innerHTML=`Additional <span>${items.length}</span>`;filters.append(filter);updateStats(items);filter.addEventListener('click',event=>{event.preventDefault();filters.querySelectorAll('button').forEach(b=>b.classList.toggle('is-active',b===filter));syncAdditional(card,items)});filters.addEventListener('click',event=>{const btn=event.target.closest('button[data-filter]');if(!btn||btn===filter)return;setTimeout(()=>syncAdditional(card,items),0)},true);document.querySelector('#library-search')?.addEventListener('input',()=>setTimeout(()=>syncAdditional(card,items),0));syncAdditional(card,items)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
